// Replicate the core logic to verify rules & patterns
const COLS=88, ROWS=50;
const makeGrid=()=>Array.from({length:ROWS},()=>new Uint8Array(COLS));

function neighbors(grid,x,y,wrap=true){
  let n=0;
  for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
    if(dx===0&&dy===0)continue;
    let nx=x+dx,ny=y+dy;
    if(wrap){nx=(nx+COLS)%COLS;ny=(ny+ROWS)%ROWS;}
    else if(nx<0||nx>=COLS||ny<0||ny>=ROWS)continue;
    n+=grid[ny][nx];
  }
  return n;
}
function tick(grid,wrap=true){
  const next=makeGrid();
  for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){
    const n=neighbors(grid,x,y,wrap);
    const a=grid[y][x];
    next[y][x]=(a?(n===2||n===3):(n===3))?1:0;
  }
  return next;
}

// Test 1: solitary cell dies (underpopulation)
let g=makeGrid(); g[25][40]=1;
let t=tick(g);
console.log('T1 solitary dies:', t[25][40]===0 ? 'PASS':'FAIL');

// Test 2: 2-cell stays dead (no birth)
g=makeGrid(); g[25][40]=1; g[25][41]=1;
t=tick(g);
console.log('T2 block of 2 no birth (pop 0):', count(t)===0?'PASS':'FAIL');

// Test 3: blinker oscillator (3 in a row -> 3 in a column)
g=makeGrid();
[[25,40],[25,41],[25,42]].forEach(([y,x])=>{g[y][x]=1;});
t=tick(g);
const hits = [];
for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)if(t[y][x])hits.push([y,x]);
const ok = hits.length===3 && hits.every(([y,x])=>x===41 && (y===24||y===25||y===26));
console.log('T3 blinker oscillates:', ok?'PASS':'FAIL');

// Test 4: block (2x2) is stable
g=makeGrid();
[[25,40],[25,41],[26,40],[26,41]].forEach(([y,x])=>{g[y][x]=1;});
t=tick(g);
console.log('T4 block stable (pop 4):', count(t)===4?'PASS':'FAIL');

// Test 5: glider moves and retains population 5
function seedPattern(names){
  const glider=[[0,0],[1,0],[2,0],[0,1],[1,2]];
  g=makeGrid();
  glider.forEach(([x,y])=>{g[y+24][x+40]=1;});
  let before=count(g);
  let moved=false;
  let g2=g;
  for(let i=0;i<4;i++){ g2=tick(g2); }
  // glider should have translated diagonally; population still 5
  console.log('T5 glider pop stays 5 after 4 gens:', count(g2)===5?'PASS':'FAIL');
}
function count(gr){let n=0;for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)n+=gr[y][x];return n;}

seedPattern();
console.log('--- done ---');
